#' Delayed-Entry Cox Regression
#'
#' Fits Cox regression with left truncation (delayed entry) for one 
#' independent participant per row. Enter start and stop times from the same 
#' origin in the same units. Stop is the event or censoring time, not duration 
#' since entry. Only baseline covariates and one binary endpoint are 
#' supported.
#' @param data A data frame with one independent participant per row.
#' @param entrytime Numeric entry time since the shared origin.
#' @param exittime Numeric exit time since the same origin, in the same units
#'   as entry time.
#' @param event Binary event indicator: 0 = censored, 1 = event. Logical
#'   FALSE/TRUE or factor labels 0/1 also work.
#' @param predictors Numeric or categorical baseline predictors. Categorical
#'   predictors use the first observed factor level as the reference (in factor
#'   level order).
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guidance} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$sample} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$estimates} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$sample$asDF}
#'
#' \code{as.data.frame(results$sample)}
#'
#' @export
delayedentrycox <- function(
    data,
    entrytime = NULL,
    exittime = NULL,
    event = NULL,
    predictors = NULL) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("delayedentrycox requires jmvcore to be installed (restart may be required)")

    if ( ! missing(entrytime)) entrytime <- jmvcore::resolveQuo(jmvcore::enquo(entrytime))
    if ( ! missing(exittime)) exittime <- jmvcore::resolveQuo(jmvcore::enquo(exittime))
    if ( ! missing(event)) event <- jmvcore::resolveQuo(jmvcore::enquo(event))
    if ( ! missing(predictors)) predictors <- jmvcore::resolveQuo(jmvcore::enquo(predictors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(entrytime), entrytime, NULL),
            `if`( ! missing(exittime), exittime, NULL),
            `if`( ! missing(event), event, NULL),
            `if`( ! missing(predictors), predictors, NULL))


    options <- delayedentrycoxOptions$new(
        entrytime = entrytime,
        exittime = exittime,
        event = event,
        predictors = predictors)

    analysis <- delayedentrycoxClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

